window.__votdWeek && window.__votdWeek({"week":"2029-05-14","reading":"Doctrine and Covenants 46–48","days":[{"d":"2029-05-14","ref":"D&C 46:14","b":"D&C","c":46,"v":14,"he":"לַאֲחֵרִים נִתַּן לְהַאֲמִין בְּדִבְרֵיהֶם לְמַעַן יִהְיוּ לָהֶם גַּם חַיֵּי עוֹלָם אִם יַעַמְדוּ נֶאֱמָנִים׃","en":"To others it is given to believe on their words, that they also might have eternal life if they continue faithful."},{"d":"2029-05-15","ref":"D&C 46:15","b":"D&C","c":46,"v":15,"he":"וְעוֹד לִקְצָתָם נִתַּן בְּיַד רוּחַ־הַקֹּדֶשׁ לָדַעַת שֹׁנוֹת הָעֲבֹדוֹת כַּטּוֹב בְּעֵינֵי יְהוָה כִּרְצוֹן יְהוָה עֹרֵךְ רַחֲמָיו לְדֶרֶךְ בְּנֵי הָאָדָם׃","en":"And again, to some it is given by the Holy Ghost to know the differences of administration, as it will be pleasing unto the same Lord, according as the Lord will, suiting his mercies according to the conditions of the children of men."},{"d":"2029-05-16","ref":"D&C 46:32","b":"D&C","c":46,"v":32,"he":"וְהוֹדוּ לֵאלֹהִים בָּרוּחַ עַל כׇּל בְּרָכָה אֲשֶׁר תְּבֹרָכוּ׃","en":"And ye must give thanks unto God in the Spirit for whatsoever blessing ye are blessed with."},{"d":"2029-05-17","ref":"D&C 47:1","b":"D&C","c":47,"v":1,"he":"הִנֵּה נָכוֹן בִּי כִּי עַבְדִּי ג׳וֹן יִכְתֹּב וְיִשְׁמֹר דִּבְרֵי יָמִים סְדוּרִים וְיַעֲזֹר לְךָ עַבְדִּי יוֹסֵף לְהַעְתִּיק כׇּל הַנִּתָּן לְךָ עַד הִקָּרְאוֹ לַעֲבוֹדוֹת נוֹסָפוֹת׃","en":"Behold, it is expedient in me that my servant John should write and keep a regular history, and assist you, my servant Joseph, in transcribing all things which shall be given you, until he is called to further duties."},{"d":"2029-05-18","ref":"D&C 48:2","b":"D&C","c":48,"v":2,"he":"וּכְפִי אֲשֶׁר יֵשׁ־לָכֶם אֲדָמוֹת תַּחְלְקוּ לָאַחִים מִן הַמִּזְרָח׃","en":"And inasmuch as ye have lands, ye shall impart to the eastern brethren;"},{"d":"2029-05-19","ref":"D&C 48:4","b":"D&C","c":48,"v":4,"he":"נָחוּץ כִּי תַחְשְׂכוּ כׇּל הַכֶּסֶף אֲשֶׁר תּוּכְלוּ וְתַשִּׂיגוּ כׇּל אֲשֶׁר תּוּכְלוּ בְּצֶדֶק לְמַעַן בְּעִתּוֹ תּוּכְלוּ לִקְנוֹת אֶרֶץ לְנַחֲלָה גַּם הָעִיר׃","en":"It must needs be necessary that ye save all the money that ye can, and that ye obtain all that ye can in righteousness, that in time ye may be enabled to purchase land for an inheritance, even the city."},{"d":"2029-05-20","ref":"D&C 48:5","b":"D&C","c":48,"v":5,"he":"הַמָּקוֹם טֶרֶם יִגָּלֶה אַךְ אַחֲרֵי בוֹא אֲחֵיכֶם מִן הַמִּזְרָח יְמֻנּוּ אֲנָשִׁים וְלָהֶם יִנָּתֵן לָדַעַת הַמָּקוֹם אוֹ לָהֶם יִגָּלֶה׃","en":"The place is not yet to be revealed; but after your brethren come from the east there are to be certain men appointed, and to them it shall be given to know the place, or to them it shall be revealed."}]});
